"""Regenerate Great Docs recipe pages from usage.py code builders."""

from __future__ import annotations

import ast
import textwrap
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable

ROOT = Path(__file__).resolve().parents[1]
USAGE_PATH = ROOT / "usage.py"
RECIPES_DIR = ROOT / "great-docs" / "recipes"
GENERATED_BANNER = (
    "<!-- Generated by scripts/generate_recipes.py. "
    "Edit usage.py to change the code examples. -->"
)

BUILDER_HELPERS = (
    "serialize_states_code_value",
    "resolve_states_demo_config",
    "format_table_property_value",
)


@dataclass(frozen=True)
class RecipeSpec:
    slug: str
    title: str
    description: str
    source: str
    builder_name: str
    builder_kwargs: dict[str, Any] | None = None
    builder_args: tuple[Any, ...] | None = None
    media: str | None = None
    sections: tuple[tuple[str, str, dict[str, Any] | None, tuple[Any, ...] | None], ...] | None = None


def extract_function_sources(names: set[str]) -> dict[str, str]:
    source = USAGE_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)
    extracted: dict[str, str] = {}

    for node in tree.body:
        if isinstance(node, ast.FunctionDef) and node.name in names:
            segment = ast.get_source_segment(source, node)
            if segment:
                extracted[node.name] = textwrap.dedent(segment)

    missing = names - set(extracted)
    if missing:
        raise RuntimeError(f"Missing builder functions in usage.py: {sorted(missing)}")

    return extracted


def exec_usage_preamble(namespace: dict[str, Any]) -> None:
    source = USAGE_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)
    preamble_nodes: list[ast.stmt] = []
    for node in tree.body:
        if isinstance(node, ast.FunctionDef) and node.name.startswith("build_"):
            break
        preamble_nodes.append(node)

    module = ast.Module(body=preamble_nodes, type_ignores=[])
    exec(compile(module, str(USAGE_PATH), "exec"), namespace)


def build_usage_namespace(recipes: list[RecipeSpec]) -> dict[str, Any]:
    names = {spec.builder_name for spec in recipes}
    for recipe in recipes:
        if recipe.sections:
            names.update(section[1] for section in recipe.sections)
    names.update(BUILDER_HELPERS)

    namespace: dict[str, Any] = {"__builtins__": __builtins__}
    exec_usage_preamble(namespace)
    for name, source in extract_function_sources(names).items():
        exec(source, namespace, namespace)

    return namespace


def resolve_builder_kwargs(
    recipe: RecipeSpec, namespace: dict[str, Any]
) -> dict[str, Any] | None:
    if recipe.builder_kwargs is None:
        return None

    resolved = dict(recipe.builder_kwargs)
    if (
        recipe.builder_name == "build_table_properties_code"
        and resolved.get("config") is None
    ):
        resolved["config"] = namespace["TABLE_PROPERTIES_DEFAULTS"]
    if recipe.builder_name == "build_states_code":
        resolved = {**namespace["STATES_DEMO_DEFAULTS"], **resolved}
    return resolved


def call_builder(
    namespace: dict[str, Any],
    builder_name: str,
    *,
    builder_kwargs: dict[str, Any] | None = None,
    builder_args: tuple[Any, ...] | None = None,
) -> str:
    builder = namespace[builder_name]
    if builder_kwargs is not None:
        return builder(**builder_kwargs)
    if builder_args is not None:
        return builder(*builder_args)
    return builder()


def render_code_block(code: str) -> str:
    return "\n".join(["```python", code.rstrip(), "```", ""])


def render_recipe_page(recipe: RecipeSpec, namespace: dict[str, Any]) -> str:
    frontmatter = "\n".join(
        [
            "---",
            f"title: {recipe.title}",
            f"description: {recipe.description!r}",
            "bread-crumbs: false",
            "---",
            "",
        ]
    )
    body = [
        GENERATED_BANNER,
        "",
        f"# {recipe.title}",
        "",
        recipe.description,
        "",
        f"Source: `{recipe.source}`.",
        "",
    ]

    if recipe.media:
        body.extend(
            [
                f"![{recipe.title} preview](../assets/examples/{recipe.media})",
                "",
            ]
        )

    if recipe.sections:
        for heading, builder_name, kwargs, args in recipe.sections:
            code = call_builder(
                namespace,
                builder_name,
                builder_kwargs=kwargs,
                builder_args=args,
            )
            body.extend([f"## {heading}", "", render_code_block(code)])
    else:
        code = call_builder(
            namespace,
            recipe.builder_name,
            builder_kwargs=resolve_builder_kwargs(recipe, namespace),
            builder_args=recipe.builder_args,
        )
        body.append(render_code_block(code))

    return frontmatter + "\n".join(body)


def render_index(recipes: list[RecipeSpec]) -> str:
    frontmatter = "\n".join(
        [
            "---",
            "title: Recipes",
            "description: Copy-pasteable examples generated from usage.py.",
            "bread-crumbs: false",
            "---",
            "",
        ]
    )
    lines = [
        GENERATED_BANNER,
        "",
        "# Recipes",
        "",
        "These examples are generated from the code snippets that power the "
        "interactive `usage.py` demo, so the documentation and local demo stay "
        "anchored to the same source.",
        "",
    ]
    for recipe in recipes:
        lines.extend(
            [
                f"## [{recipe.title}]({recipe.slug}.qmd)",
                "",
                recipe.description,
                "",
            ]
        )
    return frontmatter + "\n".join(lines)


