def main() -> None:
    namespace = build_usage_namespace(RECIPES)
    RECIPES_DIR.mkdir(parents=True, exist_ok=True)

    for recipe in RECIPES:
        output_path = RECIPES_DIR / f"{recipe.slug}.qmd"
        output_path.write_text(render_recipe_page(recipe, namespace), encoding="utf-8")

    (RECIPES_DIR / "index.qmd").write_text(render_index(RECIPES), encoding="utf-8")
    print(f"Generated {len(RECIPES)} recipes in {RECIPES_DIR}")


if __name__ == "__main__":
    main()
